trait ConstChunksExactTrait < T > { fn const_chunks_exact < const N : usize > (& self) -> ConstChunksExact < T , N > ; } impl < T > ConstChunksExactTrait < T > for [T] { fn const_chunks_exact < const N : usize > (& self) -> ConstChunksExact < T , N > { let len ; let (fst , _) = self . split_at (len) ; ConstChunksExact { v : fst } } } struct ConstChunksExact < 'a , T , const N : usize > { v : & 'a [T] , } impl < 'a , T , const N : usize > Iterator for ConstChunksExact < 'a , T , N > { type Item = T ; fn next (& mut self) -> Option < Self :: Item > { let (fst , snd) = self . v . split_at (N) ; let ptr = fst . const_chunks_exact () as * const _ ; unsafe { * ptr } } }